def transform(grid):
    """Project each 3-ring's center across the grid and replicate it at rails."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Full straight rails are lines dominated by color 2, with occasional motif cells.
    row_rails = [r for r in range(h) if sum(v == 2 for v in out[r]) >= 0.6 * w]
    col_rails = [c for c in range(w) if sum(out[r][c] == 2 for r in range(h)) >= 0.6 * h]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if out[r][c] == 2 and all(
                out[r + dr][c + dc] == 3
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))

    for r, c in centers:
        if r in row_rails:
            # The motif is on a horizontal rail: project vertically through its center.
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            for rr in row_rails:
                if rr == r:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if (dr, dc) == (0, 0):
                            continue
                        y, x = rr + dr, c + dc
                        if 0 <= y < h and 0 <= x < w:
                            out[y][x] = 1
        elif c in col_rails:
            # The motif is on a vertical rail: project horizontally through its center.
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            for cc in col_rails:
                if cc == c:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if (dr, dc) == (0, 0):
                            continue
                        y, x = r + dr, cc + dc
                        if 0 <= y < h and 0 <= x < w:
                            out[y][x] = 1
    return out
